package com.azure.resourcemanager.mediaservices.models;

import com.azure.core.annotation.Fluent;
import com.azure.core.util.logging.ClientLogger;
import com.fasterxml.jackson.annotation.JsonIgnore;
import com.fasterxml.jackson.annotation.JsonProperty;
import java.util.ArrayList;
import java.util.List;

@Fluent
public final class TrackSelection {
    @JsonIgnore private final ClientLogger logger = new ClientLogger(TrackSelection.class);
    private List<String> selectedTracks;

    // Constructor to initialize the TrackSelection object with the given list of track names
    public TrackSelection(List<String> trackNames) {
        this.selectedTracks = new ArrayList<>(trackNames);
    }

    // Method to add a track to the selection
    public TrackSelection addTrack(String trackName) {
        this.selectedTracks.add(trackName);
        return this;
    }

    // Method to remove a track from the selection
    public TrackSelection removeTrack(String trackName) {
        this.selectedTracks.remove(trackName);
        return this;
    }

    // Method to get the currently selected tracks as a list
    public List<String> getSelectedTracks() {
        return new ArrayList<>(selectedTracks);
    }
}
```

